import {seedBank} from './questions.js';
import {correct,shuffle,remaining,validateBank,score} from './core.js';
import {mainlandProfile,makePapers} from './mainland.js';
const KEY='pmp-room-v1', app=document.querySelector('#app'), labels={home:'学习概览',practice:'情境练习',exam:'限时小测',wrong:'错题复习',favorites:'我的收藏',history:'学习记录',library:'题库与资料',quiz:'正在答题',result:'本次结果'};
const blank=()=>({stats:{},favorites:[],history:[],session:null,custom:null});
let data=blank(),storageOK=true,page='home',result=null,pendingFile=null,toastTimer;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&typeof s==='object'){if(s.custom)validateBank(s.custom);if(!s.stats||!Array.isArray(s.favorites)||!Array.isArray(s.history))throw Error();data={...blank(),...s};}}catch{storageOK=false;}
let bank=data.custom||seedBank;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>bank.find(q=>q.id===id);
const selectedQs=s=>s.questions||s.ids.map(byId).filter(Boolean);
const clock=n=>`${Math.floor(n/3600)?String(Math.floor(n/3600)).padStart(2,'0')+':':''}${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const pct=(a,b)=>b?Math.round(a/b*100):0;
const date=t=>new Date(t).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true;}catch{storageOK=false;toast('浏览器未能保存数据，请导出备份，关闭页面可能丢失本次记录。');}}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',5000);}
function ask(title,message,action){const d=document.querySelector('#confirm-dialog');document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-text').textContent=message;d.onclose=()=>{if(d.returnValue==='ok')action();};d.showModal();}
function go(p){page=p;render();window.scrollTo({top:0,behavior:'instant'});}
function head(title,sub){return `<div class="page-head"><div><div class="eyebrow">YOUR PMP PRACTICE ROOM</div><h1>${title}</h1><p>${sub}</p></div><span class="date">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span></div>`;}
function domainsHTML(){return ['人员','过程','商业环境'].map(d=>{const qs=bank.filter(q=>q.domain===d),done=qs.filter(q=>data.stats[q.id]?.attempts),right=done.filter(q=>data.stats[q.id]?.lastCorrect);return `<div class="domain-row"><div class="domain-top"><span>${d}</span><span class="subtle">已练 ${done.length} / ${qs.length} · 最近答对 ${right.length}</span></div><div class="bar"><span style="width:${pct(done.length,qs.length)}%"></span></div></div>`;}).join('');}
function freshQuestions(count){
  const fresh=shuffle(bank.filter(q=>!data.stats[q.id]?.attempts));
  const old=shuffle(bank.filter(q=>data.stats[q.id]?.attempts));
  return [...fresh,...old].slice(0,count);
}
function presetCards(){
  if(data.custom)return '<div class="note">正在使用导入题库。若需本次新增的大陆90题，请到“题库与资料”恢复内置题库；旧学习记录保留。</div>';
  const papers=makePapers(bank);
  return `<section class="presets" aria-label="直接刷题"><div class="section-title"><h2>选一组，直接开始</h2><span>三组共90题 · 组间不重复</span></div><div class="paper-grid">${papers.map(p=>`<button class="paper-button" data-paper="${p.id}"><span>0${p.id}</span><strong>综合练习 · 第${p.id}组</strong><small>${p.questions.length}题 · 不限时 · 立即刷题 ↗</small></button>`).join('')}</div><div class="half-card"><div><h3>90题半程训练</h3><p>120分钟 · 交卷后统一解析 · 按新版领域比例近似编排</p></div><button class="primary" data-action="half">开始限时训练 →</button></div></section>`;
}
function home(){const stats=Object.values(data.stats),attempts=stats.reduce((s,x)=>s+x.attempts,0),right=stats.reduce((s,x)=>s+x.right,0),wrong=bank.filter(q=>data.stats[q.id]?.lastCorrect===false).length;return head('上海 / 广东，打开就练。','中国大陆 PMP 新版备考 · 90 道中文情境题 · 逐项解析与错题复习')+(data.session?`<div class="resume"><span>你有一场未完成的${data.session.mode==='exam'?'限时小测':'情境练习'}，已答 ${Object.keys(data.session.answers).length} / ${data.session.ids.length} 题。</span><button class="primary" data-action="resume">继续答题 →</button></div>`:'')+`<section class="hero"><div><div class="eyebrow">SMALL STEPS. BETTER DECISIONS.</div><h2>学会在情境中，<br>做出更好的项目决策。</h2><p>上海与广东使用同一大陆大纲。先刷 10 题热身，或选择下方的 30 题分组与 90 题限时训练。</p><button class="primary" data-action="quick">开始今日练习 <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span>✓</span><i>✦</i></div></div></section>${presetCards()}<section class="stats"><div class="stat"><div class="stat-label">题库题目 <span>▦</span></div><div class="stat-number">${bank.length}<small>道原创题</small></div></div><div class="stat"><div class="stat-label">已练题目 <span>▤</span></div><div class="stat-number">${bank.filter(q=>data.stats[q.id]?.attempts).length}<small>道</small></div></div><div class="stat"><div class="stat-label">累计正确率 <span>↗</span></div><div class="stat-number">${attempts?pct(right,attempts)+'%':'—'}<small>${attempts?'含重复练习':'开始后显示'}</small></div></div><div class="stat"><div class="stat-label">待复习错题 <span>↻</span></div><div class="stat-number">${wrong}<small>道</small></div></div></section><div class="section-title"><h2>选择今天的练习方式</h2><span>每天一点，持续积累</span></div><section class="mode-grid"><button class="mode-card" data-page="practice"><span class="mode-icon">▤</span><h3>情境练习</h3><p>按领域和交付方法筛选，提交后查看逐项解析。</p><div class="card-bottom"><span>理解考点 · 即时反馈</span><b>↗</b></div></button><button class="mode-card" data-page="exam"><span class="mode-icon">◷</span><h3>限时小测</h3><p>在限定时间内独立作答，交卷后集中复盘。</p><div class="card-bottom"><span>训练节奏 · 刷新续考</span><b>↗</b></div></button><button class="mode-card" data-page="wrong"><span class="mode-icon">↻</span><h3>错题复习</h3><p>回到尚未掌握的知识点，把错误变成进步。</p><div class="card-bottom"><span>${wrong} 道待复习 · 答对后移出</span><b>↗</b></div></button></section><div class="lower-grid"><section><div class="section-title"><h2>三个领域，逐步掌握</h2><span>按已练题目统计</span></div><div class="panel">${domainsHTML()}</div></section><section><div class="section-title"><h2>开始之前</h2><span>备考提醒</span></div><div class="panel"><h3>上海 / 广东 · 中国大陆通用</h3><p class="tip">PMI 中国公告：大陆新版自 2026 年 12 月 5 日启用，正式考试 180 题、240 分钟。地区不改变备考大纲，具体考务以准考信为准。</p><div class="note">本套 90 道原创模拟练习，按新版三大领域编排，尚未经过独立专家复核；90 题训练不是完整正式考试仿真。<br><a href="${mainlandProfile.source}" target="_blank" rel="noopener">查看 PMI 中国依据 ↗</a></div></div></section></div>`;}
function pool(mode,domain='全部',approach='全部'){return bank.filter(q=>(domain==='全部'||q.domain===domain)&&(approach==='全部'||q.approach===approach)&&(mode!=='wrong'||data.stats[q.id]?.lastCorrect===false)&&(mode!=='favorites'||data.favorites.includes(q.id)));}
function setup(mode){const qs=pool(mode),exam=mode==='exam';if(!qs.length)return head(labels[mode],mode==='wrong'?'做错的题会自动收进这里。':'把值得再看的题留给未来的自己。')+`<div class="panel empty"><div class="mode-icon">${mode==='wrong'?'✓':'☆'}</div><h2>${mode==='wrong'?'暂时没有待复习错题':'还没有收藏题目'}</h2><p>${mode==='wrong'?'开始练习后，答错或未答的题会出现在这里。':'答题时点击收藏，即可在这里单独练习。'}</p><div class="actions" style="justify-content:center"><button class="primary" data-page="practice">开始情境练习 →</button></div></div>`;return head(labels[mode],exam?'训练专注力与答题节奏，交卷后再查看答案。':'仔细阅读情境，选择最合适的下一步。')+`<div class="setup"><section class="panel"><div class="chips"><span class="chip">${exam?'到时自动交卷':'不限时 · 逐题解析'}</span><span class="chip">单选 + 多选</span><span class="chip">可用 ${qs.length} 题</span></div><form id="setup-form" data-mode="${mode}"><div class="form-grid"><label class="field">知识领域<select id="domain"><option>全部</option><option>人员</option><option>过程</option><option>商业环境</option></select></label><label class="field">交付方法<select id="approach"><option>全部</option><option>预测</option><option>敏捷</option><option>混合</option></select></label><label class="field">抽取题数<input id="count" type="number" min="1" max="${qs.length}" value="${Math.min(exam?90:10,qs.length)}" required></label>${exam?'<label class="field">作答时间（分钟）<input id="minutes" type="number" min="1" max="300" value="120" required></label>':'<label class="field">题目顺序<select id="order"><option value="random">随机顺序</option><option value="ordered">题库顺序</option></select></label>'}</div><p id="pool-count" class="subtle">当前筛选可用 ${qs.length} 题；同场不重复抽题。</p><div class="note">${exam?'这是自定义限时训练；90题/120分钟用于半程节奏训练，不复刻正式180题试卷及完整案例模块。刷新或关闭页面不会暂停小测计时，返回后仍按原截止时间交卷。':'多选题需要完整选中所有正确答案，少选、多选都记为错误。答题后可查看每个选项的理由。'}</div><div class="actions"><button type="submit" class="primary">${exam?'开始限时小测':'开始练习'} →</button><button type="button" class="secondary" data-page="home">返回概览</button></div></form></section></div>`;}
function start(mode,qs,minutes,label){if(!qs.length)return toast('当前筛选没有可用题目。');const launch=()=>{data.session={mode,label,questions:qs,ids:qs.map(q=>q.id),answers:{},checked:[],flags:[],index:0,start:Date.now(),deadline:mode==='exam'?Date.now()+minutes*60000:null};save();go('quiz');};if(data.session)ask('替换未完成的答题？','开始新的一场将替换当前未完成答题；已记录的历史与逐题练习结果会保留。',launch);else launch();}
function record(q,answer){const stat=data.stats[q.id]||{attempts:0,right:0};const ok=correct(q,answer);stat.attempts++;stat.right+=Number(ok);stat.lastCorrect=ok;stat.lastAt=Date.now();data.stats[q.id]=stat;}
function rationale(q,a){const ok=correct(q,a);return `<div class="rationale"><h3>${ok?'✓ 回答正确':'↻ 再理解一次'} <span class="subtle">正确答案 ${q.answer.map(i=>String.fromCharCode(65+i)).join('、')}</span></h3>${q.rationales.map((r,i)=>`<p><strong>${String.fromCharCode(65+i)} · ${q.answer.includes(i)?'正确选项':'其他选项'}</strong><br>${esc(r)}</p>`).join('')}<p class="subtle">${esc(q.status||'导入题目，请核对来源与答案')}</p></div>`;}
function quiz(){const s=data.session;if(!s){page='home';return home();}const qs=selectedQs(s),q=qs[s.index],a=s.answers[q.id]||[],checked=s.checked.includes(q.id),fav=data.favorites.includes(q.id);return `<div class="quiz-header"><div><div class="eyebrow">${s.mode==='exam'?'TIMED PRACTICE':'SCENARIO PRACTICE'}</div><h2>${esc(s.label||(s.mode==='exam'?'限时小测':'情境练习'))} <span class="subtle">${s.index+1} / ${qs.length}</span></h2></div><div class="actions" style="margin:0">${s.deadline?`<span class="timer" id="timer">${clock(remaining(s))}</span>`:''}<button class="secondary" data-page="home">返回概览</button></div></div><div class="quiz-layout"><section class="panel"><div class="chips"><span class="chip">${esc(q.domain)}</span><span class="chip">${esc(q.approach)}</span><span class="chip">${q.answer.length>1?'多选 · 选择 '+q.answer.length+' 项':'单选'}</span><span class="chip">${esc(q.topic)}</span></div><h1 class="question">${esc(q.stem)}</h1><div class="options">${q.options.map((o,i)=>`<label class="option ${checked?(q.answer.includes(i)?'good':a.includes(i)?'bad':''):''}"><input type="${q.answer.length>1?'checkbox':'radio'}" name="answer" value="${i}" ${a.includes(i)?'checked':''} ${checked?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span>${esc(o)}</span></label>`).join('')}</div>${checked?rationale(q,a):''}<div class="actions"><button class="secondary" data-action="prev" ${s.index===0?'disabled':''}>← 上一题</button>${s.mode!=='exam'&&!checked?'<button class="primary" data-action="check">提交答案</button>':''}<button class="${s.mode==='exam'?'primary':'secondary'}" data-action="next" ${s.index===qs.length-1?'disabled':''}>下一题 →</button><button class="secondary" data-action="favorite">${fav?'★ 已收藏':'☆ 收藏'}</button><button class="secondary" data-action="flag">${s.flags.includes(q.id)?'⚑ 已标记':'⚐ 标记'}</button></div></section><aside class="quiz-side"><div class="panel"><h3>答题导航</h3><div class="progress-line"><span style="width:${pct(Object.values(s.answers).filter(x=>x.length).length,qs.length)}%"></span></div><div class="number-grid">${qs.map((x,i)=>`<button aria-label="第 ${i+1} 题${s.answers[x.id]?.length?'，已作答':''}${s.flags.includes(x.id)?'，已标记':''}" class="num ${i===s.index?'current':''} ${s.answers[x.id]?.length?'answered':''} ${s.flags.includes(x.id)?'flagged':''}" data-index="${i}">${i+1}</button>`).join('')}</div><p class="legend">浅绿：已选择答案<br>圆点：标记待检查<br>${s.deadline?'计时持续进行，截止后自动交卷。':'提交答案后该题锁定，可继续查看解析。'}</p><button class="primary" style="width:100%;margin-top:16px" data-action="finish">${s.mode==='exam'?'交卷并查看结果':'结束并查看结果'}</button></div></aside></div>`;}
function finish(){const s=data.session;if(!s)return;const qs=selectedQs(s);for(const q of qs)if(!s.checked.includes(q.id))record(q,s.answers[q.id]||[]);result={...score(qs,s.answers),label:s.label,questions:qs,answers:s.answers,mode:s.mode,at:Date.now(),seconds:Math.floor(((s.deadline?Math.min(Date.now(),s.deadline):Date.now())-s.start)/1000)};data.history.unshift(result);data.history=data.history.slice(0,100);data.session=null;save();go('result');}
function results(){if(!result)return head('本次结果','暂无结果。');return head('每一次复盘，都有收获。','先看懂错误，再继续下一场练习。')+`<section class="panel score-card"><span class="chip">${esc(result.label||(result.mode==='exam'?'限时诊断小测':'情境练习'))} · ${result.total} 道题</span><div class="score-number">${result.percent}<small>%</small></div><p>答对 ${result.right} / ${result.total} 题 <span class="subtle">· 用时 ${clock(result.seconds)}</span></p><p class="tip">这是本套题目的正确率，不表示官方通过标准或通过概率。</p><div class="result-grid">${Object.entries(result.domains).map(([d,v])=>`<div class="result-mini">${d}<strong>${v.right} / ${v.total}</strong></div>`).join('')}</div><div class="actions" style="justify-content:center"><button class="primary" data-page="wrong">复习错题 →</button><button class="secondary" data-page="home">返回概览</button></div></section><div class="section-title"><h2>逐题复盘</h2><span>未答题按错误计入</span></div>${result.questions.map((q,i)=>`<details class="review-item"><summary>${correct(q,result.answers[q.id])?'✓':'↻'} ${i+1}. ${esc(q.stem)}</summary><p>你的答案：${(result.answers[q.id]||[]).map(i=>String.fromCharCode(65+i)).join('、')||'未作答'}</p>${q.options.map((o,i)=>`<p>${String.fromCharCode(65+i)}. ${esc(o)}</p>`).join('')}${rationale(q,result.answers[q.id]||[])}</details>`).join('')}`;}
function history(){return head('让进步，看得见。','保留最近 100 场已结束的练习和小测，可查看当时的题目与答案。')+`<section class="panel">${data.history.length?data.history.map((r,i)=>`<div class="history-row"><div><strong>${esc(r.label||(r.mode==='exam'?'限时小测':'情境练习'))} · ${r.total} 道题</strong><small>${date(r.at)} · 用时 ${clock(r.seconds)} · 答对 ${r.right} 题</small></div><div class="actions" style="margin:0"><span class="history-percent">${r.percent}%</span><button class="secondary" data-history="${i}">复盘</button></div></div>`).join(''):'<div class="empty"><h2>学习记录从下一次开始</h2><p>结束一场练习或小测后，结果会保存在这里。</p></div>'}</section><div class="note">记录保存在当前浏览器，不自动在电脑和手机之间同步。可在“题库与资料”导出、导入学习备份。清理浏览器数据会丢失本地记录。</div>`;}
function library(){return head('好题目，从清楚的依据开始。','题库、备份和经核对的 GitHub 项目放在这里。')+`<section class="panel"><h2>当前题库 · ${bank.length} 道题</h2><p class="tip">${data.custom?'正在使用你导入的题库。':'内置 90 道原创情境题初稿。人员 30 题、过程 37 题、商业环境 23 题，覆盖预测、敏捷和混合方法；每题含答案及各选项解析。'} 上海与广东适用相同的大陆大纲，本套面向2026年12月起新版备考；题量、难度和题型覆盖度不能等同正式考试。</p><div class="actions"><button class="primary" data-action="export-bank">导出 JSON 题库</button><button class="secondary" data-action="import-bank">导入 JSON 题库</button>${data.custom?'<button class="secondary" data-action="reset-bank">恢复内置题库</button>':''}</div><div class="note">导入格式可参考导出的 JSON。answer 使用从 0 开始的选项下标；每项选项均需 rationales 解析。只导入自己有权使用的题目，题库导入会替换当前题库和未完成答题。</div><div class="section-title"><h3>学习记录备份</h3></div><p class="tip">导出当前题库、错题、收藏、历史和未完成答题。导入会替换此浏览器的学习数据；文件包含个人学习记录，请自行妥善保管。</p><div class="actions"><button class="secondary" data-action="export-backup">导出学习备份</button><button class="secondary" data-action="import-backup">导入学习备份</button></div></section><div class="section-title"><h2>GitHub 项目参考</h2><span>核对日期：2026-11-10</span></div><section class="panel"><a class="source-link" href="https://github.com/Indexasp74/PMP-Exam-Sim" target="_blank" rel="noopener">Indexasp74 / PMP-Exam-Sim ↗<small>PMP 专用模拟器，计时、领域统计与 AI 生成题目；需要自己的模型 API Key。生成答案仍需复核。</small></a><a class="source-link" href="https://github.com/Aristote-code/pmp-2026-practice-simulator" target="_blank" rel="noopener">Aristote-code / pmp-2026-practice-simulator ↗<small>README 声明有 4 套 180 题及多题型交互。项目较新，题目质量和运行结果尚未逐项验证。</small></a><a class="source-link" href="https://github.com/WasteRoadJ/PracticeMaster" target="_blank" rel="noopener">WasteRoadJ / PracticeMaster ↗<small>通用中文刷题工具，支持 Excel 导入、错题强化与自定义限时测试；不自带 PMP 专项题库。</small></a><a class="source-link" href="https://github.com/emacle/pmp" target="_blank" rel="noopener">emacle / pmp ↗<small>中文旧版备考资料与模拟卷，围绕 PMBOK 第六版，适合补充参考，不能直接代表当前考纲。</small></a></section><div class="section-title"><h2>官方考试依据</h2></div><section class="panel"><a class="source-link" href="${mainlandProfile.source}" target="_blank" rel="noopener">PMI 中国：大陆新版考试更新 ↗<small>大陆自2026年12月5日启用新版：180题、240分钟。领域权重为人员33%、过程41%、业务环境26%。核对日期：${mainlandProfile.verified}。</small></a><a class="source-link" href="${mainlandProfile.outline}" target="_blank" rel="noopener">下载中国大陆适用的2026年12月考试大纲 ↗<small>题目为依据大纲主题编排的原创练习，不是官方样题、真题或独立审定题库。</small></a><a class="source-link" href="https://www.pmi.org/certifications/project-management-pmp" target="_blank" rel="noopener">PMI：报名资格、培训要求与考试说明 ↗<small>刷题可以辅助备考，但不能替代报名要求、项目经验和所需培训。</small></a><p class="tip">本题库为 AI 辅助撰写的原创初稿，未复制官方或商业题库。尚未经过独立 PMP 专家审校；发现歧义时，应结合适用大纲与权威教材核对。</p></section>`;}
function render(){document.querySelector('#page-label').textContent=labels[page]||labels.home;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('#wrong-count').textContent=bank.filter(q=>data.stats[q.id]?.lastCorrect===false).length;app.innerHTML=({home,quiz,result:results,history,library}[page]||(()=>setup(page)))();if(!storageOK)app.insertAdjacentHTML('afterbegin','<p class="warning" role="alert">浏览器存储不可用或记录无法读取。请使用导出备份保存学习记录。</p>');if(document.querySelector('#setup-form')){['domain','approach'].forEach(id=>document.querySelector('#'+id).addEventListener('change',()=>{const n=pool(page,document.querySelector('#domain').value,document.querySelector('#approach').value).length;const input=document.querySelector('#count');input.max=Math.max(1,n);input.value=Math.min(Number(input.value)||1,Math.max(1,n));document.querySelector('#pool-count').textContent=`当前筛选可用 ${n} 题；同场不重复抽题。`;document.querySelector('#setup-form [type=submit]').disabled=!n;}));}}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
document.addEventListener('submit',e=>{if(e.target.id!=='setup-form')return;e.preventDefault();const mode=e.target.dataset.mode,qs=pool(mode,document.querySelector('#domain').value,document.querySelector('#approach').value),n=Number(document.querySelector('#count').value);if(!Number.isInteger(n)||n<1||n>qs.length)return toast('抽取题数超出可用范围。');start(mode,(document.querySelector('#order')?.value==='ordered'?qs:shuffle(qs)).slice(0,n),Number(document.querySelector('#minutes')?.value||0));});
document.addEventListener('change',e=>{if(e.target.name!=='answer'||!data.session)return;const s=data.session,q=selectedQs(s)[s.index];if(s.checked.includes(q.id))return;const a=[...document.querySelectorAll('[name=answer]:checked')].map(x=>Number(x.value));if(a.length)s.answers[q.id]=a;else delete s.answers[q.id];save();const nav=document.querySelector(`[data-index="${s.index}"]`);nav?.classList.toggle('answered',a.length>0);const bar=document.querySelector('.progress-line span');if(bar)bar.style.width=pct(Object.values(s.answers).filter(x=>x.length).length,s.ids.length)+'%';});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page)return go(b.dataset.page);if(b.dataset.paper!==undefined){const paper=makePapers(bank).find(p=>p.id===Number(b.dataset.paper));if(paper)return start('practice',paper.questions,undefined,paper.title);}if(b.dataset.history!==undefined){result=data.history[Number(b.dataset.history)];return go('result');}const s=data.session;if(b.dataset.index!==undefined&&s){s.index=Number(b.dataset.index);save();return go('quiz');}const action=b.dataset.action;if(!action)return;if(action==='resume')return go('quiz');if(action==='quick')return start('practice',freshQuestions(10),undefined,'10题热身练习');if(action==='half')return start('exam',shuffle(bank).slice(0,90),120,'大陆新版 · 90题半程训练');if(action==='export-bank')return download('pmp-question-bank.json',bank);if(action==='export-backup')return download('pmp-learning-backup.json',{format:'pmp-room-backup-v1',at:Date.now(),bank,data});if(action==='import-bank'||action==='import-backup'){pendingFile=action;const input=document.querySelector('#file-input');input.value='';input.click();return;}if(action==='reset-bank')return ask('恢复内置题库？','当前题库和未完成答题将被替换。学习统计、收藏及历史保留。',()=>{data.custom=null;data.session=null;bank=seedBank;save();go('library');});if(!s)return;const q=selectedQs(s)[s.index];if(action==='prev'||action==='next'){s.index+=action==='next'?1:-1;save();go('quiz');}if(action==='check'){const a=s.answers[q.id]||[];if(!a.length)return toast('请先选择答案。');if(s.checked.includes(q.id))return;record(q,a);s.checked.push(q.id);save();render();}if(action==='favorite'){data.favorites=data.favorites.includes(q.id)?data.favorites.filter(id=>id!==q.id):[...data.favorites,q.id];save();render();}if(action==='flag'){s.flags=s.flags.includes(q.id)?s.flags.filter(id=>id!==q.id):[...s.flags,q.id];save();render();}if(action==='finish'){const unanswered=s.ids.filter(id=>!s.answers[id]?.length).length;ask('结束本次答题？',unanswered?`还有 ${unanswered} 道题未作答，交卷后将按错误计入。`:'交卷后可以查看全部答案与解析。',finish);}});
function validateBackup(v){if(v?.format!=='pmp-room-backup-v1'||!v.data||typeof v.data!=='object')throw Error('不是有效的学习备份。');validateBank(v.bank);const d=v.data;if(!d.stats||typeof d.stats!=='object'||Array.isArray(d.stats)||!Array.isArray(d.favorites)||d.favorites.some(x=>typeof x!=='string')||!Array.isArray(d.history)||d.history.length>100)throw Error('学习记录格式不正确。');for(const st of Object.values(d.stats)){if(!st||!Number.isInteger(st.attempts)||!Number.isInteger(st.right)||st.right<0||st.attempts<st.right||typeof st.lastCorrect!=='boolean')throw Error('统计格式不正确。');}function validAnswers(qs,a){if(!a||typeof a!=='object'||Array.isArray(a))throw Error('答案格式不正确。');for(const [id,ans] of Object.entries(a)){const q=qs.find(q=>q.id===id);if(!q||!Array.isArray(ans)||new Set(ans).size!==ans.length||ans.some(i=>!Number.isInteger(i)||i<0||i>=q.options.length))throw Error('答案选项不正确。');}}for(const r of d.history){validateBank(r.questions);validAnswers(r.questions,r.answers);if(!Number.isFinite(r.at)||!Number.isFinite(r.seconds)||r.seconds<0)throw Error('历史记录时间不正确。');Object.assign(r,score(r.questions,r.answers));}if(d.session){const s=d.session;validateBank(s.questions);validAnswers(s.questions,s.answers);if(!['practice','exam','wrong','favorites'].includes(s.mode)||!Number.isInteger(s.index)||s.index<0||s.index>=s.questions.length||!Number.isFinite(s.start)||!Array.isArray(s.checked)||!Array.isArray(s.flags)||s.checked.some(id=>!s.questions.some(q=>q.id===id))||s.flags.some(id=>!s.questions.some(q=>q.id===id))||(s.mode==='exam'&&!Number.isFinite(s.deadline)))throw Error('未完成答题格式不正确。');s.ids=s.questions.map(q=>q.id);}return v;}
document.querySelector('#file-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>12*1024*1024)return toast('文件过大，请使用12MB以内的JSON文件。');try{const v=JSON.parse(await file.text());if(pendingFile==='import-bank'){validateBank(v);ask('替换当前题库？',`将导入 ${v.length} 道题，并结束未完成答题。历史记录保留；若复用相同id，旧统计会关联到新题。`,()=>{bank=v;data.custom=v;data.session=null;save();go('library');toast('题库已导入。');});}else{validateBackup(v);ask('替换本机学习记录？','建议先导出当前备份。导入后将替换题库、错题、收藏、历史和未完成答题。',()=>{data={...blank(),...v.data,custom:v.bank};bank=v.bank;result=null;save();go('home');toast('学习备份已恢复。');});}}catch(err){toast('导入失败：'+err.message);}});
setInterval(()=>{const s=data.session;if(s?.mode==='exam'){const n=remaining(s),el=document.querySelector('#timer');if(el){el.textContent=clock(n);el.classList.toggle('urgent',n<300);}if(n===0){const d=document.querySelector('#confirm-dialog');if(d.open){d.onclose=null;d.close('cancel');}finish();toast('答题时间已到，已自动交卷。');}}},1000);
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('home');});
validateBank(seedBank);render();
if(location.hash==='#practice')go('practice');
if(location.hash==='#start'){if(data.session)go('quiz');else start('practice',freshQuestions(10),undefined,'10题热身练习');}
if(location.hash==='#exam')go('exam');
